/** An MCP server's own name: `server` with any `plugin_<plugin>_` prefix dropped. */
function mcpServerName(server: string): string {
  return server.startsWith("plugin_") ? server.slice(7).replace(/^[^_]*_/, "") : server;
}

/**
 * Whether `server` (an MCP tool name's server segment) is one the floor knows
 * by name: the org profile lists read-only tools for it, a plugin's copy
 * included. Every MCP
 * tool the profile doesn't list as read-only (nor FloorConfig.readOnlyMcpTools)
 * is held as outward, since a tool's name says nothing reliable about what it
 * does; the exceptions are the profile's checkout, self-filed and review
 * write tools, whose reach the floor reads from the call itself.
 */
export function knownMcpServer(server: string, profile: OrgProfile = DEFAULT_ORG_PROFILE): boolean {
  return orgKnownMcpServer(profile, server);
}

