/** Words after which a `/` in awk starts a regex, not a division (`getline` returns a value, so it isn't one). */
const AWK_REGEX_AFTER_WORD = new Set(["print", "printf", "return", "in", "case", "else", "do"]);

/** Where the awk regex opened at `i` (a `/`) ends: the index of its closing `/`, or -1 when none does on its line. */
function awkRegexEnd(program: string, i: number): number {
  let bracket = false;
  for (let j = i + 1; j < program.length && program[j] !== "\n"; j++) {
    const c = program[j]!;
    if (c === "\\") j++;
    else if (bracket) {
      // `[:alpha:]`, `[.x.]` and `[=x=]` inside a bracket end at their own `:]`, `.]`, `=]`.
      if (c === "[" && /[:.=]/.test(program[j + 1] ?? "")) {
        const close = program.indexOf(`${program[j + 1]}]`, j + 2);
        if (close > 0 && !program.slice(j, close).includes("\n")) j = close + 1;
      } else if (c === "]") bracket = false;
    } else if (c === "[") {
      bracket = true;
      // `[]…]` and `[^]…]`: a `]` first in a bracket is part of it.
      if (program[j + 1] === "^") j++;
      if (program[j + 1] === "]") j++;
    } else if (c === "/") return j;
  }
  return -1;
}

/**
 * An awk program with its string literals replaced by `\u0001N\u0001` (the
 * Nth of `strings`, still escaped), its regex literals by `\u0002`, and its
 * comments dropped, in one pass, so a `"` in a regex or a `/` in a string
 * can't throw the reading of the rest off. A `/` after a value (`)`, `]`, a
 * name, a number, `x++`) is read as division, as awk mostly does, unless
 * `flip` names it (or is "all"); `ambiguous` lists those whose reading as a
 * regex would mask a quote, a comment, a pipe or a command, so the caller can
 * read the program that way too.
 */
function maskAwk(source: string, flip: ReadonlySet<number> | "all" = new Set()): { masked: string; strings: string[]; ambiguous: number[] } {
  const program = source.replace(/\\\r?\n/g, " ");
  const strings: string[] = [];
  let masked = "";
  const ambiguous: number[] = [];
  // The last non-space character written.
  let prev = "";
  for (let i = 0; i < program.length; ) {
    const c = program[i]!;
    if (c === "#") {
      const end = program.indexOf("\n", i);
      i = end < 0 ? program.length : end;
      continue;
    }
    if (c === '"') {
      let j = i + 1;
      while (j < program.length && program[j] !== '"' && program[j] !== "\n") j += program[j] === "\\" ? 2 : 1;
      masked += `\u0001${strings.push(program.slice(i + 1, Math.min(j, program.length))) - 1}\u0001`;
      prev = "x";
      i = j + 1;
      continue;
    }
    if (c === "/") {
      const word = /([A-Za-z_]\w*)\s*$/.exec(masked)?.[1];
      const postfix = /(?:\+\+|--)\s*$/.test(masked);
      const regex = !postfix && (prev === "" || /[(,~!{};&|=<>+\-*%^?:[\n]/.test(prev) || (word !== undefined && AWK_REGEX_AFTER_WORD.has(word)));
      const end = awkRegexEnd(program, i);
      const suspect = !regex && end > 0 && /["#|@]|\bsystem\b|\bgetline\b/.test(program.slice(i + 1, end));
      if (suspect) ambiguous.push(i);
      if ((regex || (suspect && (flip === "all" || flip.has(i)))) && end > 0) {
        masked += "\u0002";
        prev = "x";
        i = end + 1;
        continue;
      }
    }
    masked += c;
    if (!/\s/.test(c) || c === "\n") prev = c;
    i++;
  }
  return { masked, strings, ambiguous };
}

/** sqlite3 dot-command input with every space its shell splits on (`\v`, `\f`, `\r`) as a plain one. */
function sqliteSpaces(text: string): string {
  return text.replace(/[\v\f\r]/g, " ");
}

/** A sqlite3 dot-command argument as the shell reads it: unquoted, and a double-quoted one with its escapes decoded. */
function sqliteArg(word: string): string {
  const w = word.trim();
  if (/^'.*'$/s.test(w)) return w.slice(1, -1);
  if (!/^".*"$/s.test(w)) return w;
  const named: Record<string, string> = { a: "\x07", b: "\b", t: "\t", n: "\n", v: "\v", f: "\f", r: "\r" };
  return w.slice(1, -1).replace(/\\([0-7]{1,3}|x[0-9a-fA-F]{1,2}|[\s\S])/g, (_, e: string) =>
    /^[0-7]/.test(e) ? String.fromCharCode(parseInt(e, 8)) : /^x./.test(e) ? String.fromCharCode(parseInt(e.slice(1), 16)) : (named[e] ?? e),
  );
}

/**
 * A sqlite3 dot-command line split as its shell splits it: spaces after the
 * `.` skipped, then words, each quoted one read by `sqliteArg`; null when the
 * line isn't a dot-command.
 */
function sqliteDotTokens(line: string): string[] | null {
  const m = /^[ \t]*\.(.*)$/s.exec(line);
  if (!m) return null;
  const s = m[1]!;
  const tokens: string[] = [];
  for (let i = 0; i < s.length; ) {
    while (i < s.length && /[ \t]/.test(s[i]!)) i++;
    if (i >= s.length) break;
    let end: number;
    if (s[i] === '"') {
      end = i + 1;
      while (end < s.length && s[end] !== '"') end += s[end] === "\\" ? 2 : 1;
      end = Math.min(end + 1, s.length);
    } else if (s[i] === "'") {
      const close = s.indexOf("'", i + 1);
      end = close < 0 ? s.length : close + 1;
    } else {
      end = i;
      while (end < s.length && !/[ \t]/.test(s[end]!)) end++;
    }
    tokens.push(sqliteArg(s.slice(i, end)));
    i = end;
  }
  return tokens;
}

/** An awk string literal's text, with its escapes decoded (`\163` and `\x73` are `s`, `\h` is `h`). */
function decodeAwkString(text: string): string {
  const named: Record<string, string> = { a: "\x07", b: "\b", f: "\f", n: "\n", r: "\r", t: "\t", v: "\v" };
  return text.replace(/\\([0-7]{1,3}|x[0-9a-fA-F]{1,2}|[\s\S])/g, (_, e: string) =>
    /^[0-7]/.test(e) ? String.fromCharCode(parseInt(e, 8)) : /^x./.test(e) ? String.fromCharCode(parseInt(e.slice(1), 16)) : (named[e] ?? e),
  );
}

/**
 * Text bash may run a substitution in when it evaluates it as arithmetic: a name's `[` subscript
 * followed anywhere by `$(`, `$[`, `${` or a backtick (subscripts nest, and `${v@P}` re-expands a value).
 */
const SUBSCRIPT_RUNS = /[A-Za-z_]\w*\[[\s\S]*(?:\$[([{]|\x60)/;

