const PLAYWRIGHT_CLI = /(?:^|\/)(?:@playwright\/test|playwright(?:-core|-chromium)?)\/cli\.[cm]?js$/;


/** Code that reads the owner secret or builds the owner's sign-in URL: Standup's owner-token module and the web console's owner proxy. */
