/** Most entries under a temp repository's `refs` and `logs` the floor checks for links out of it (Classifier.selfContainedGitDir). */
const GIT_DIR_SCAN_CAP = 2000;

/**
 * Config keys a repository's own config may hold that name nowhere to fetch
 * from or push to and run no command: what `git init` writes, and settings
 * that only change how git reads or shows the repository. Sections outside
 * these (`remote`, `url` insteadOf rewrites, `branch` upstreams,
 * `include`/`includeIf`, `extensions`) and keys that name a program or a
 * file git reads more config or hooks from (`core.editor`, `core.fsmonitor`,
 * `core.hooksPath`, `diff.external`, …) are not among them.
 */
const LOCAL_GIT_KEYS: ReadonlySet<string> = new Set([
  "core.repositoryformatversion", "core.filemode", "core.bare", "core.logallrefupdates", "core.ignorecase", "core.precomposeunicode",
  "core.symlinks", "core.autocrlf", "core.safecrlf", "core.eol", "core.quotepath", "core.abbrev",
  "user.name", "user.email", "init.defaultbranch",
  "commit.verbose", "commit.status", "commit.cleanup", "tag.sort",
  "advice.detachedhead", "advice.statushints", "advice.pushupdaterejected", "advice.resolveconflict", "advice.addignoredfile", "advice.defaultbranchname",
  "color.ui", "color.diff", "color.status", "color.branch", "color.interactive",
  "gc.auto", "i18n.commitencoding", "i18n.logoutputencoding",
  "log.decorate", "log.abbrevcommit", "log.date", "log.follow", "log.showroot", "log.mailmap",
  "diff.renames", "diff.algorithm", "diff.mnemonicprefix", "diff.noprefix", "diff.context", "diff.indentheuristic", "diff.statgraphwidth",
  "status.showuntrackedfiles", "status.short", "status.branch", "status.relativepaths",
]);

/** Stands for every repository in Classifier.gitConfigChanged: a change to user, system or file-named config. */
const ANY_REPO = "\0any";

/** The hooks a push runs in the repository it pushes to. */
const RECEIVE_HOOKS = ["pre-receive", "update", "proc-receive", "post-receive", "post-update", "reference-transaction", "push-to-checkout"] as const;

/** Receive-side settings a scratch push target may hold beside LOCAL_GIT_KEYS: they refuse or allow updates and run nothing. */
const SCRATCH_RECEIVE_KEYS: ReadonlySet<string> = new Set(["receive.denycurrentbranch", "receive.denydeletecurrent", "receive.denynonfastforwards", "receive.denydeletes"]);

/** A transient unit `systemd-run` names when given no `--unit`: `run-u<N>.service`, `run-<N>.scope`, `run-r<id>.scope`. */
const TRANSIENT_UNIT = /^run-[ru]?[0-9a-f]+\.(?:service|scope)$/;

/** A systemd unit name as systemctl reads it: `.service` added to one with no unit type suffix. */
function unitName(name: string): string {
  return /\.(?:service|socket|device|mount|automount|swap|target|path|timer|slice|scope)$/.test(name) ? name : `${name}.service`;
}

/** `decodeURIComponent`, or null for text it can't decode. */
function decodeURIComponentSafe(text: string): string | null {
  try {
    return decodeURIComponent(text);
  } catch {
    return null;
  }
}

/** The keys a scratch repository's `[remote "<name>"]` and `[branch "<name>"]` sections may hold (scratchGitConfig). */
const SCRATCH_REMOTE_KEYS: ReadonlySet<string> = new Set(["url", "fetch"]);
const SCRATCH_BRANCH_KEYS: ReadonlySet<string> = new Set(["remote", "merge"]);

/** A remote or branch name git config may carry as a subsection, without quotes or escapes to read. */
const GIT_SUBSECTION_NAME = /^[A-Za-z0-9._\/-]+$/;

/**
 * The remotes a scratch repository's config file names, by name and URL, or
 * null when the file holds anything else. Beside LOCAL_GIT_KEYS under plain
 * `[section]` headers, it may hold `[remote "<name>"]` sections with only
 * `url` and `fetch`, each url one `isScratchUrl` passes, and `[branch "<name>"]`
 * sections with only `remote` (naming a remote the file defines, or `.`) and
 * `merge`. Any other subsection (`[url …]` rewrites, `[include…]`), key
 * (`pushurl`, `push`, `mirror`, `uploadpack`, `receivepack`, `proxy`, `vcs`,
 * `promisor`, `pushRemote`) or line git reads differently than it looks
 * refuses: git also starts a section at a `[` later on a line, reads `\r` as
 * a line break and joins a line ending in `\` to the next. `extraKeys` are
 * further `section.key` names allowed under plain headers.
 */
function scratchGitConfig(text: string, isScratchUrl: (url: string) => boolean, extraKeys: ReadonlySet<string> = new Set()): Map<string, string[]> | null {
  if (text.includes("\r")) return null;
  let section: string | null = null;
  let sub: string | null = null;
  const remotes = new Map<string, string[]>();
  const branchRemotes: string[] = [];
  for (const line of text.split("\n")) {
    const t = line.trim();
    if (t === "" || t.startsWith("#") || t.startsWith(";")) continue;
    if (t.endsWith("\\")) return null;
    const header = /^\[([A-Za-z0-9-]+)(?:\s+"([^"\\]*)")?\]\s*(?:[#;].*)?$/.exec(t);
    if (header) {
      section = header[1]!.toLowerCase();
      sub = header[2] ?? null;
      if (sub !== null && (!(section === "remote" || section === "branch") || !GIT_SUBSECTION_NAME.test(sub))) return null;
      if (section === "remote" && sub !== null && !remotes.has(sub)) remotes.set(sub, []);
      continue;
    }
    if (t.indexOf("[", 1) >= 0 || t.startsWith("[")) return null;
    const entry = /^([A-Za-z][A-Za-z0-9-]*)\s*(?:=\s*(.*))?$/.exec(t);
    if (!entry || section === null) return null;
    const key = entry[1]!.toLowerCase();
    if (sub === null) {
      if (!LOCAL_GIT_KEYS.has(`${section}.${key}`) && !extraKeys.has(`${section}.${key}`)) return null;
      continue;
    }
    const raw = (entry[2] ?? "").replace(/\s+[#;].*$/, "").trim();
    const value = /^"[^"\\]*"$/.test(raw) ? raw.slice(1, -1) : raw;
    if (/["\\]/.test(value)) return null;
    if (section === "remote") {
      if (!SCRATCH_REMOTE_KEYS.has(key)) return null;
      if (key === "url") {
        if (!isScratchUrl(value)) return null;
        remotes.get(sub)!.push(value);
      }
    } else {
      if (!SCRATCH_BRANCH_KEYS.has(key)) return null;
      if (key === "remote") branchRemotes.push(value);
    }
  }
  if (!branchRemotes.every((r) => r === "." || remotes.has(r))) return null;
  return remotes;
}

/** Git environment that moves the config, repository or attributes a checkout reads its attributes from. */
const GIT_ATTRIBUTE_ENV = ["GIT_CONFIG_GLOBAL", "GIT_CONFIG_SYSTEM", "GIT_CONFIG_PARAMETERS", "GIT_CONFIG_COUNT", "GIT_ATTR_SOURCE", "GIT_DIR", "GIT_COMMON_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE"];

/** `git restore`'s long options; each but `--ours` and `--theirs` also takes a `--no-` form. */
const RESTORE_LONG = ["source", "staged", "worktree", "ignore-unmerged", "overlay", "quiet", "recurse-submodules", "progress", "merge", "conflict", "ours", "theirs", "patch", "ignore-skip-worktree-bits", "pathspec-from-file", "pathspec-file-nul"];
const RESTORE_NAMES = [...RESTORE_LONG, ...RESTORE_LONG.filter((n) => n !== "ours" && n !== "theirs").map((n) => `no-${n}`)];
/** `git restore`'s long options that take a value, as the next argument or after `=`. */
const RESTORE_VALUED: ReadonlySet<string> = new Set(["source", "conflict", "pathspec-from-file"]);
/** `git restore`'s short flags other than `-s` (which takes a value), as their long names. */
const RESTORE_SHORT: Readonly<Record<string, string>> = { S: "--staged", W: "--worktree", q: "--quiet", m: "--merge", p: "--patch", "2": "--ours", "3": "--theirs" };

/**
 * `git restore`'s arguments read as git reads them: each option by its full
 * long name (git takes any unambiguous prefix of one, and bundled short
 * flags), the paths, and the revision each `--source` names (null where the
 * floor can't tell it). Null when an option isn't one restore takes, is
 * ambiguous, or lacks its value.
 */
function restoreArgs(values: ReadonlyArray<string | null>): { opts: string[]; paths: Array<string | null>; sources: Array<string | null> } | null {
  const opts: string[] = [];
  const paths: Array<string | null> = [];
  const sources: Array<string | null> = [];
  for (let k = 0, ended = false; k < values.length; k++) {
    const v = values[k] ?? null;
    if (!ended && v === "--") ended = true;
    else if (ended || v === null || !v.startsWith("-") || v === "-") paths.push(v);
    else if (v.startsWith("--")) {
      const eq = v.indexOf("=");
      const given = eq < 0 ? v.slice(2) : v.slice(2, eq);
      const matches = RESTORE_NAMES.includes(given) ? [given] : RESTORE_NAMES.filter((n) => n.startsWith(given));
      if (given === "" || matches.length !== 1) return null;
      const name = matches[0]!;
      if (RESTORE_VALUED.has(name)) {
        if (eq < 0 && k + 1 >= values.length) return null;
        const value = eq < 0 ? (values[++k] ?? null) : v.slice(eq + 1);
        if (name === "source") sources.push(value);
        else opts.push(`--${name}`);
      } else if (eq >= 0 && name !== "recurse-submodules") return null;
      else opts.push(`--${name}`);
    } else {
      for (let i = 1; i < v.length; i++) {
        const c = v[i]!;
        if (c === "s") {
          if (i + 1 === v.length && k + 1 >= values.length) return null;
          sources.push(i + 1 < v.length ? v.slice(i + 1) : (values[++k] ?? null));
          break;
        }
        const long = RESTORE_SHORT[c];
        if (long === undefined) return null;
        opts.push(long);
      }
    }
  }
  return { opts, paths, sources };
}

/** Built-ins whose own `-h` is an option rather than git's usage text (`grep -h` drops file names, `ls-remote -h` lists branches). */
const GIT_DASH_H_OPTION: ReadonlySet<string> = new Set(["grep", "ls-remote", "show-ref"]);
/** Built-ins with subcommands that each print their own usage for a `-h` or `--help` right after them. */
const GIT_HELP_SUBCOMMANDS: Readonly<Record<string, ReadonlySet<string>>> = {
  stash: new Set(["push", "save", "apply", "pop", "drop", "branch", "clear", "create", "store"]),
  worktree: new Set(["add", "list", "lock", "move", "prune", "remove", "repair", "unlock"]),
  remote: new Set(["add", "rename", "remove", "rm", "set-head", "set-branches", "get-url", "set-url", "show", "prune", "update"]),
};

/**
 * Whether git prints a built-in's usage and exits for these arguments, before
 * it reads any other: `--help` first (git runs it as `git help <sub>`), `-h`
 * first where the built-in has no `-h` of its own, or either right after a
 * subcommand that takes it so.
 */
/** Variables that change which viewer, pager or browser `git … --help` runs, or where it finds them. */
const HELP_VIEWER_ENV: ReadonlySet<string> = new Set(["PATH", "MANPATH", "MANPAGER", "PAGER", "BROWSER", "HOME", "XDG_CONFIG_HOME", "LESS", "LESSOPEN", "LESSKEY"]);

function gitHelpForm(sub: string, values: ReadonlyArray<string | null>): boolean {
  const first = values[0];
  if (first === "--help") return true;
  // A built-in prints its usage for a lone `-h`; with more words after it, some read `-h` as an option and the rest as operands.
  if (first === "-h") return values.length === 1 && !GIT_DASH_H_OPTION.has(sub);
  const subs = GIT_HELP_SUBCOMMANDS[sub];
  return subs !== undefined && first != null && subs.has(first) && values.length === 2 && (values[1] === "-h" || values[1] === "--help");
}

/** Programs that change no files or refs, so they may come before a checkout the floor reads (Classifier.localCheckout). */
const PRELUDE_SAFE: ReadonlySet<string> = new Set(["cd", "pushd", "popd", "pwd", "echo", "printf", "true", ":", "test", "[", "[[", "set", "date", "sleep"]);

/** git subcommands that change no files, refs or config (unlike `fetch`, which can update a local branch through its refspec). */
