  "add", "apply", "bisect", "branch", "bundle", "checkout", "checkout-index", "citool", "clean", "commit-graph",
  "commit-tree", "config", "credential", "credential-cache", "credential-store", "fast-export", "fast-import",
  "fetch-pack", "filter-branch", "fmt-merge-msg", "for-each-repo", "gc", "gui", "hash-object", "index-pack",
  "instaweb", "mailinfo", "mailsplit", "maintenance", "merge-file", "merge-index", "merge-tree", "mergetool",
  "mktag", "mktree", "multi-pack-index", "mv", "notes", "p4", "pack-objects", "pack-refs", "prune", "prune-packed",
  "read-tree", "receive-pack", "reflog", "remote", "repack", "replace", "request-pull", "rerere", "restore", "rm",
  "sparse-checkout", "stage", "stash", "stripspace", "submodule", "svn", "switch", "symbolic-ref", "tag",
