        if (del.path !== null) this.checkWrite(del.path, "delete", `code in ${label}`, text, mode);
        else this.hold("destructive", `code in ${label} removes a tree above ${del.base === "dir" ? "its own dir" : del.base === "cwd" ? "its cwd" : del.base === "tmp" ? "the temp dir" : "a value"}, at a path the floor can't place (${text})`, text, false, false, "deny");
