    // part of its argv line (`["git", "commit", "-m", "stop; rm -rf /"]`); the
    // same text anywhere else in the file is still read on its own.
    const argvs = execSink ? execSinkArgvs(scanned) : [];
    const argvWords = new Set(argvs.flatMap((a) => a.literals.slice(1)));
    const argvJoined = new Set(argvs.map((a) => a.literals.map((k) => scanned.literals[k]!).join(" ")));
