    // Outside a runner's file nothing runs in a placed fixture dir, so no run is placed there.
    const localSinks = local && execSink ? execSinkCommands(scanned, () => false, true, false, home.aliases).texts.filter((s) => !argvJoined.has(s)) : [];
    const sinkTexts = new Set(sinks ? sinks.texts : [...lines, ...localSinks, ...runtimeRun.lines]);
