      const bareTool = this.policyTool(s.trim()) && (!fromFile || commandSink) && !(scanned.dataWords.has(s) && !execSink);
      const wordList = fromFile && !execSink && !scanned.literals.includes(s) && /^[\w.-]+(?: [\w.-]+)+$/.test(s) && s.split(" ").every((w) => scanned.unionWords.has(w));
